function transactionRows(text){text=text.replace(/^\uFEFF/,'');const delimiter=text.split(/\r?\n/,1)[0].includes(';')?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV incomplet : guillemets non fermés.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows;}
function summarizeBTC(text){const rows=transactionRows(text),head=rows.shift();const required=['Type','Date','Montant reçu','Monnaie ou jeton reçu','Montant envoyé','Monnaie ou jeton envoyé','Frais','Monnaie ou jeton des frais','ID Externe'];if(!required.every(k=>head.includes(k)))throw Error('Format non reconnu. Utilisez l’export de transactions avec colonnes Type, Date, Montant reçu…');let sat=0,euros=0,fees=0,count=0,duplicates=0,first='',last='';const ids=new Set();function num(s){const n=Number(s.replace(',','.'));if(!s.trim()||!Number.isFinite(n)||n<0)throw Error('Montant invalide.');return n;}for(const row of rows.filter(r=>r.some(Boolean))){if(row.length!==head.length)throw Error('Ligne CSV incomplète.');const a=Object.fromEntries(head.map((h,i)=>[h,row[i].trim()]));const id=a['ID Externe'];if(!id)throw Error('Identifiant de transaction manquant.');if(ids.has(id)){duplicates++;continue;}ids.add(id);if(!['Échange','Dépôt'].includes(a.Type)||a['Monnaie ou jeton reçu']!=='BTC'||(a['Montant envoyé']&&num(a['Montant envoyé'])!==0&&a['Monnaie ou jeton envoyé']!=='EUR')||(a.Frais&&num(a.Frais)!==0&&a['Monnaie ou jeton des frais']!=='EUR'))throw Error('Ce fichier contient des opérations non prises en charge (vente, retrait ou frais en crypto). Import annulé.');if(!/^\d{4}-\d{2}-\d{2}T/.test(a.Date)||isNaN(Date.parse(a.Date))||a.Date.slice(0,10)>today())throw Error('Date de transaction invalide.');const btc=num(a['Montant reçu']);const units=Math.round(btc*1e8);if(Math.abs(btc*1e8-units)>1e-5||!Number.isSafeInteger(units))throw Error('Précision BTC invalide.');sat+=units;if(!Number.isSafeInteger(sat))throw Error('Quantité BTC trop importante.');euros+=a['Montant envoyé']?num(a['Montant envoyé']):0;fees+=a.Frais?num(a.Frais):0;count++;first=!first||a.Date<first?a.Date:first;last=a.Date>last?a.Date:last;}if(!count)throw Error('Aucune opération exploitable.');return {btc:sat/1e8,euros,fees,count,duplicates,first,last};}
let btcSummary=null;
$('#cryptoImport').onclick=()=>{btcSummary=null;$('#cryptoResult').textContent='Choisissez votre export CSV. Le fichier est traité dans ce navigateur uniquement.';$('#btcPrice').value='';$('#btcDate').value=today();$('#btcDate').max=today();$('#cryptoSave').disabled=true;$('#cryptoModal').showModal();};$('#cryptoClose').onclick=()=>$('#cryptoModal').close();
$('#cryptoFile').onchange=async e=>{btcSummary=null;$('#cryptoSave').disabled=true;try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('Fichier trop volumineux (maximum 5 Mo).');btcSummary=summarizeBTC(await f.text());$('#cryptoResult').textContent=`${btcSummary.count} opérations · ${btcSummary.btc.toFixed(8)} BTC reçus · ${money(btcSummary.euros)} envoyés · ${money(btcSummary.fees)} de frais déclarés séparément. ${btcSummary.duplicates} doublon(s) ignoré(s). Période : ${btcSummary.first.slice(0,10)} au ${btcSummary.last.slice(0,10)}. Vérifiez que cet historique est complet et correspond à votre solde actuel.`;$('#cryptoSave').disabled=false;}catch(err){$('#cryptoResult').textContent=err.message;}e.target.value='';};
$('#cryptoForm').onsubmit=e=>{e.preventDefault();if(!btcSummary)return;const price=Number($('#btcPrice').value);if(!Number.isFinite(price)||price<=0||!validDate($('#btcDate').value)||$('#btcDate').value<btcSummary.last.slice(0,10)){toast('Renseignez un cours positif et une date au moins égale à la dernière opération, sans dépasser aujourd’hui.');return;}const amount=Math.round(btcSummary.btc*price*100)/100;if(amount>1e14){toast('Valorisation trop élevée.');return;}const current=demo?[]:assets;const existing=current.find(a=>a.provider==='Bitstack'&&a.category==='Crypto'&&a.name==='Épargne Bitcoin (import transactions)');if(existing&&!confirm('Remplacer votre précédent import de transactions Bitstack par ce solde recalculé ?'))return;const a={id:existing?.id||crypto.randomUUID(),provider:'Bitstack',name:'Épargne Bitcoin (import transactions)',category:'Crypto',amount,valuationDate:$('#btcDate').value,notes:`${btcSummary.btc.toFixed(8)} BTC × ${price} €/BTC · ${btcSummary.count} opérations. Cours et solde confirmés manuellement.`};if(commit(existing?current.map(x=>x.id===existing.id?a:x):[...current,a])){$('#cryptoModal').close();toast('Valorisation Bitcoin enregistrée. Vérifiez l’absence d’une autre ligne Bitstack comptant le même solde.');}};
